function marketAcceptAIDraft(text){
  const match=String(text||'').match(/\[\[MARKET_PAGE_DRAFT:(\{[^\n]*\})\]\]/);
  if(!match)return false;
  try{
    const proposal=JSON.parse(match[1]),context=marketPageContext(),allowed=new Set(context.allowedWidgets);
    if(proposal.scope!==context.scope||proposal.baseVersion!==context.baseVersion)throw Error('页面在生成期间发生变化，请基于当前页面重新生成。');
    if(!['update','create'].includes(proposal.mode))throw Error('请先确认是调整当前页，还是新建页面。');
    if(!Array.isArray(proposal.widgets)||!proposal.widgets.length||proposal.widgets.length>16||proposal.widgets.some(id=>!allowed.has(id)))throw Error('AI 返回了不可用的组件');
    const widgets=[...new Set(proposal.widgets)],name=String(proposal.name||'').trim().slice(0,40);
    if(proposal.mode==='create'){
      if(MS.newPageDraft?.scope===context.scope)throw Error('请先保存或取消当前的新页面草稿。');
      if(!name)throw Error('新页面需要名称');
      if(widgets.some(id=>!context.readyWidgets.includes(id)))throw Error('新页面使用了尚无可用数据的看板，请改用已有数据源。');
      const source=marketCurrent(),page={id:marketNewWorkId(),kind:context.kind,name,group:'自定义',description:widgets.map(marketWidgetName).slice(0,3).join(' · '),sourceTemplate:source.sourceTemplate||source.id,sourceFundCode:context.kind==='detail'?MS.fundCode:null,widgets,createdAt:new Date().toISOString()};
      MS.newPageDraft={scope:context.scope,page,updatedAt:new Date().toISOString()};MS.preview=page;MS.editing=false;
      MS.landingHome=false;
      if(MS.view==='community'||MS.view==='my-pages'||state.nav==='pages'){MS.view=context.kind==='detail'?'fund':'home';state.nav='market'}
      MS.newPageMode=true;MS.saveFeedback='';MS.notice='';
    }else{
      if(marketLandingHome())throw Error('看行情首页固定展示大盘和自选；如需调整，请新建个人页面。');
      if(MS.view==='community'){MS.view='home';state.nav='market'}
      if(marketActiveNewPageDraft()){
        MS.newPageDraft.page.widgets=widgets;if(name)MS.newPageDraft.page.name=name;
        MS.newPageDraft.updatedAt=new Date().toISOString();MS.preview=MS.newPageDraft.page;
        MS.saveFeedback='';MS.notice='';
      }else if(MS.preview&&MS.works.some(row=>row.id===MS.preview.id)){
        const page=marketCopy(MS.preview);page.widgets=widgets;if(name)page.name=name;
        MS.newPageDraft={scope:context.scope,page,existingWorkId:page.id,updatedAt:new Date().toISOString()};
        MS.preview=page;MS.saveFeedback='';MS.notice='';
      }else{
        marketDraftFromCurrent();MS.undo.push(marketCopy(MS.draft.page));MS.redo=[];
        MS.draft.page.widgets=widgets;if(name)MS.draft.page.name=name;
        MS.draft.updatedAt=new Date().toISOString();MS.editing=true;
        MS.saveFeedback='';MS.notice='';
      }
    }
    marketPersist();return true;
  }catch(error){MS.notice=error.message||'页面草稿未生成';return false}
}
function marketAcceptAIMetricDraft(text){const match=String(text||'').match(/\[\[MARKET_METRIC_DRAFT:(\{[^\n]*\})\]\]/);if(!match)return false;try{const item=JSON.parse(match[1]);if(!['drawdown','holding-contribution'].includes(item.method)||!['1y','3m','3y'].includes(item.window))throw Error('指标方法或区间不可用');MS.metricDraft={name:String(item.name||'自定义指标').slice(0,40),method:item.method,window:item.window};MS.showMetrics=true;MS.notice='指标草稿已生成，确认后保存';return true}catch(error){MS.notice=error.message||'指标草稿未生成';return false}}

