function marketOpenLanding(){MS.view='home';MS.landingHome=true;MS.fundCode='';MS.returnTo=null;MS.fundTrail=[];MS.preview=null}
function marketActiveNewPageDraft(){return MS.preview===MS.newPageDraft?.page&&MS.newPageDraft?.scope===marketScope()?MS.newPageDraft:null}
function marketCurrent(){
  // The entry page stays small even when an older custom home layout was saved.
  if(marketLandingHome())return marketTemplate('balanced-home');
  const scope=marketScope(),kind=MS.view==='fund'?'detail':'home';
  if(MS.draft&&MS.draft.scope!==scope){MS.drafts[MS.draft.scope]=MS.draft;MS.draft=MS.drafts[scope]||null;MS.undo=[];MS.redo=[];marketPersist()}
  else if(!MS.draft&&MS.drafts[scope]){MS.draft=MS.drafts[scope];marketPersist()}
  let preview=null;
  if(MS.view==='home'||MS.view==='fund'){
    if(marketActiveNewPageDraft())preview=MS.newPageDraft.page;
    else if(MS.preview&&MS.preview!==MS.newPageDraft?.page)preview=MS.preview;
  }
  return preview||(MS.draft?.scope===scope?MS.draft.page:null)||(MS.activeWorkId&&MS.works.find(row=>row.id===MS.activeWorkId))||MS.pages[scope]||MS.pages[kind]||marketTemplate(kind==='home'?'balanced-home':'balanced-detail');
}
