function marketBack(){if(MS.fundTrail.length){MS.fundCode=MS.fundTrail.pop();MS.view='fund';render();marketEnsureFunds();marketEnsurePublic();marketEnsureEstimates();return}const origin=MS.returnTo;MS.returnTo=null;MS.fundCode='';MS.preview=null;MS.editing=false;MS.saveFeedback='';if(!origin){state.nav='market';state.selected=null;state.runFocus=null;state.drill=null;MS.activeWorkId=null;MS.newPageMode=false;MS.view='home';MS.landingHome=true;render();return}state.nav=origin.nav||'market';state.selected=origin.selected||null;state.runFocus=null;state.drill=null;state.selectedHoldingCode=origin.selectedHoldingCode||'';state.holdingsAccountScope=origin.holdingsAccountScope||state.holdingsAccountScope;MS.activeWorkId=origin.activeWorkId||null;MS.newPageMode=Boolean(origin.newPageMode);MS.landingHome=Boolean(origin.landingHome);MS.view=origin.view==='my-pages'?'my-pages':origin.view||'home';MS.fundCode=origin.fundCode||'';MS.range=origin.range||MS.range;MS.search=origin.search||'';state.composerContext=pageContext();render();if(origin.runFocus)openRun(origin.runFocus);if(state.nav==='holdings'&&state.selectedHoldingCode)loadHoldingDetail(state.selectedHoldingCode)}
