function marketOpenViewPicker(kind,returnView=MS.view,creating=false){if(creating&&MS.newPageDraft){MS.notice='请先保存或取消当前的新页面草稿';render();return}MS.communityReturn=returnView==='new-page'?'new-page':returnView==='my-pages'?'my-pages':returnView==='fund'?'fund':'home';MS.communityTab=kind==='detail'?'detail':'home';MS.saveFeedback='';if(creating){MS.activeWorkId=null;MS.newPageMode=true}MS.view='community';state.nav='market';render()}
