function marketDraftFromCurrent(){const current=marketCurrent();if(MS.draft?.scope===marketScope())return;MS.draft={scope:marketScope(),page:marketCopy(current),updatedAt:new Date().toISOString()};MS.draft.page.widgets=(MS.draft.page.widgets||[]).filter(id=>marketCanUse(id,MS.view==='fund'?'detail':'home'));MS.draft.page.id=MS.activeWorkId|| (MS.draft.page.id?.startsWith('personal-')?MS.draft.page.id:'personal-'+Date.now());MS.preview=null;MS.undo=[];MS.redo=[];marketPersist()}
