function marketSave(){const scope=marketScope();marketDraftFromCurrent();const page=marketCopy(MS.draft.page),kind=MS.view==='fund'?'detail':'home';page.kind=kind;page.savedAt=new Date().toISOString();if(MS.newPageMode){page.id=marketNewWorkId();page.createdAt=page.createdAt||page.savedAt;page.revision=1;MS.works.push(page);MS.activeWorkId=page.id;MS.newPageMode=false;MS.history[`work:${page.id}`]=[marketCopy(page)]}else if(MS.activeWorkId){const index=MS.works.findIndex(row=>row.id===MS.activeWorkId);if(index<0){MS.notice='原页面已不存在，无法保存修改';render();return}page.id=MS.activeWorkId;page.revision=(MS.works[index].revision||1)+1;MS.works[index]=page;(MS.history[scope]||(MS.history[scope]=[])).push(marketCopy(page));MS.history[scope]=MS.history[scope].slice(-20)}else{page.revision=(MS.pages[scope]?.revision||0)+1;(MS.history[scope]||(MS.history[scope]=[])).push(marketCopy(page));MS.history[scope]=MS.history[scope].slice(-20);MS.pages[scope]=page}MS.draft=null;delete MS.drafts[scope];MS.editing=false;MS.preview=null;MS.undo=[];MS.redo=[];marketSavedFeedback(page);marketPersist();render()}
function marketCommitNewPage(){const pending=MS.newPageDraft;if(!pending||pending.scope!==marketScope())return false;const page=marketCopy(pending.page),existingId=pending.existingWorkId;page.savedAt=new Date().toISOString();if(existingId){const index=MS.works.findIndex(row=>row.id===existingId);if(index<0){MS.notice='原页面已不存在，无法保存更改';render();return false}page.id=existingId;page.revision=(MS.works[index].revision||1)+1;MS.works[index]=page;(MS.history[`work:${existingId}`]||(MS.history[`work:${existingId}`]=[])).push(marketCopy(page));MS.history[`work:${existingId}`]=MS.history[`work:${existingId}`].slice(-20)}else{page.id=marketNewWorkId();page.revision=1;page.createdAt=page.createdAt||page.savedAt;MS.works.push(page);MS.history[`work:${page.id}`]=[marketCopy(page)]}MS.activeWorkId=page.id;MS.newPageMode=false;MS.preview=null;MS.newPageDraft=null;marketSavedFeedback(page);marketPersist();render();return true}
