function marketDate(value){return value?String(value).slice(0,10):'—'}
function marketSvg(points,color='#cbb995',height=112){const series=points.filter(p=>Number.isFinite(Number(p.value)));if(series.length<2)return '<div class="ms-empty">暂无可绘制的历史数据</div>';const values=series.map(p=>Number(p.value)),lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1;const path=series.map((p,i)=>`${i?'L':'M'}${(i/(series.length-1)*1000).toFixed(1)} ${((1-(Number(p.value)-lo)/span)*height+4).toFixed(1)}`).join(' ');return `<svg class="ms-chart" viewBox="0 0 1000 ${height+8}" preserveAspectRatio="none" role="img" aria-label="历史走势"><path d="${path}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`}
function marketRangePoints(points,range=MS.range){if(!points.length)return [];const end=new Date(points.at(-1).date),from=new Date(end);if(range==='all')return points;if(range==='1w')from.setDate(from.getDate()-7);else from.setMonth(from.getMonth()-({ '1m':1,'3m':3,'6m':6,'1y':12,'3y':36 }[range]||12));return points.filter(row=>new Date(row.date)>=from)}
function marketReturn(points){if(points.length<2)return null;const first=n(points[0].value),last=n(points.at(-1).value);return first>0&&last!==null?(last/first-1)*100:null}
function marketDrawdown(points){if(points.length<2)return null;let peak=Number(points[0].value),worst=0;for(const row of points){const value=Number(row.value);if(!Number.isFinite(value)||value<=0)continue;peak=Math.max(peak,value);worst=Math.min(worst,(value/peak-1)*100)}return worst}
function marketDetailChart(points){const rows=points.filter(row=>Number.isFinite(Number(row.value))&&Number(row.value)>0);if(rows.length<2)return '<div class="ms-empty">当前区间没有足够的净值数据</div>';const width=720,height=240,left=52,right=12,top=14,bottom=34,base=Number(rows[0].value),values=rows.map(row=>(Number(row.value)/base-1)*100),low=Math.min(...values),high=Math.max(...values),pad=(high-low||2)*.12,min=low-pad,max=high+pad,plotWidth=width-left-right,plotHeight=height-top-bottom;const x=i=>left+i/(rows.length-1)*plotWidth,y=value=>top+(max-value)/(max-min)*plotHeight;const path=values.map((value,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(value).toFixed(1)}`).join(' '),area=`${path} L${x(rows.length-1).toFixed(1)},${top+plotHeight} L${left},${top+plotHeight} Z`;const ticks=[0,.25,.5,.75,1].map(part=>{const yy=top+part*plotHeight,value=max-part*(max-min);return `<line x1="${left}" x2="${width-right}" y1="${yy}" y2="${yy}" class="ms-detail-gridline"/><text x="${left-8}" y="${yy+4}" text-anchor="end" class="ms-detail-axis">${value.toFixed(1)}%</text>`}).join('');const zero=min<=0&&max>=0?`<line x1="${left}" x2="${width-right}" y1="${y(0)}" y2="${y(0)}" class="ms-detail-zero"/>`:'';const dates=[0,Math.floor((rows.length-1)/2),rows.length-1].map((index,i)=>`<text x="${x(index)}" y="${height-7}" text-anchor="${i===0?'start':i===2?'end':'middle'}" class="ms-detail-axis">${marketDate(rows[index].date)}</text>`).join('');return `<svg class="ms-detail-chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${marketDate(rows[0].date)}至${marketDate(rows.at(-1).date)}的复权净值区间涨跌走势">${ticks}${zero}<path d="${area}" class="ms-detail-area"/><path d="${path}" class="ms-detail-line"/>${dates}<circle cx="${x(rows.length-1)}" cy="${y(values.at(-1))}" r="4" class="ms-detail-end"/></svg>`}
function marketMonthlyReturns(points){const months=new Map();for(const row of points){const value=n(row.value);if(value!==null&&value>0)months.set(String(row.date).slice(0,7),{date:row.date,value})}const series=[...months.entries()].sort(([a],[b])=>a.localeCompare(b));return series.slice(-13).map(([month,row],index,all)=>index?{month,value:(row.value/all[index-1][1].value-1)*100,date:row.date}:null).filter(Boolean).slice(-12)}
function marketTechnicalWidget(points){const values=points.map(row=>n(row.value)).filter(value=>value!==null&&value>0),last=values.at(-1),average=count=>values.length>=count?values.slice(-count).reduce((sum,value)=>sum+value,0)/count:null,ma20=average(20),ma60=average(60),change20=values.length>=21?(last/values.at(-21)-1)*100:null;return `<section class="ms-widget ms-analysis-widget"><header><h2>技术观察</h2><span>复权净值 · 日频</span></header><div class="ms-analysis-hero"><small>近 20 个净值日涨跌</small><strong class="${tone(change20)}">${pct(change20)}</strong><span>${marketDate(points.at(-1)?.date)}</span></div><div class="ms-analysis-rows"><div><span>20 日均线</span><b>${ma20===null?'—':ma20.toFixed(4)}</b><small>${ma20===null?'数据不足':last>=ma20?'最新值高于均线':'最新值低于均线'}</small></div><div><span>60 日均线</span><b>${ma60===null?'—':ma60.toFixed(4)}</b><small>${ma60===null?'数据不足':last>=ma60?'最新值高于均线':'最新值低于均线'}</small></div></div><small class="ms-source">均线根据已披露复权净值计算；不是盘中价格或交易信号。</small></section>`}
function marketHoldingsImpactWidget(estimate){if(!marketEstimateFresh(estimate))return `<section class="ms-widget ms-analysis-widget"><header><h2>披露重仓今日变化</h2></header><div class="ms-empty">今日重仓行情尚未更新；上次数据不作为今天的表现。</div></section>`;const holdings=estimate?.disclosedHoldings||[],quoted=holdings.filter(row=>n(row.changePct)!==null&&n(row.weightPct)!==null),weighted=quoted.length?quoted.reduce((sum,row)=>sum+Number(row.weightPct)*Number(row.changePct)/100,0):null,gainers=quoted.filter(row=>Number(row.changePct)>0).length,decliners=quoted.filter(row=>Number(row.changePct)<0).length;return `<section class="ms-widget ms-analysis-widget"><header><h2>披露重仓今日变化</h2><span>${estimate?.reportDate?'报告期 '+esc(estimate.reportDate):'报告期待读取'}</span></header><div class="ms-analysis-hero"><small>可获取行情的披露重仓加权变化</small><strong class="${tone(weighted)}">${pct(weighted)}</strong><span>${quoted.length}/${holdings.length} 只股票有行情</span></div><div class="ms-analysis-rows"><div><span>上涨</span><b class="up">${gainers} 只</b><small>公开披露重仓</small></div><div><span>下跌</span><b class="down">${decliners} 只</b><small>${esc(estimate?.asOf||'今日行情待更新')}</small></div></div><small class="ms-source">只对已披露且有行情的股票按披露占比加权；不是基金实时涨跌或完整持仓贡献。</small></section>`}
function marketManagerWidget(data,publicData){const manager=data?.manager,announcements=(publicData?.announcements||[]).filter(row=>/基金经理|增聘|离任|聘任|任职/.test(`${row.title||''}${row.type||''}`)).slice(0,3);return `<section class="ms-widget ms-analysis-widget"><header><h2>基金经理</h2><span>当前资料</span></header><div class="ms-analysis-hero"><small>现任经理</small><strong class="ms-person-name">${esc(manager||'暂未取得')}</strong><span>${esc(publicData?.profile?.name||'')}</span></div><div class="ms-manager-notices"><strong>经理相关公告</strong>${announcements.length?announcements.map(row=>row.url?`<a href="${esc(row.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(row.title)}</span><small>${esc(row.date||'')}</small></a>`:`<span>${esc(row.title)} · ${esc(row.date||'')}</span>`).join(''):'<span>当前返回的公告中没有经理变更记录</span>'}</div><small class="ms-source">经理姓名来自基金资料；任职起点与个人管理业绩暂无可靠数据。</small></section>`}
function marketEventPulseWidget(publicData){const notices=publicData?.announcements||[],latest=notices[0],change=notices.filter(row=>/基金经理|费率|分红|暂停|恢复|限购|开放/.test(`${row.title||''}${row.type||''}`));return `<section class="ms-widget ms-analysis-widget"><header><h2>公告动态</h2><span>最近返回 ${notices.length} 条</span></header><div class="ms-analysis-hero"><small>最近公告</small><strong class="ms-event-title">${esc(latest?.title||'暂无公告')}</strong><span>${esc(latest?.date||'—')} ${latest?.type?'· '+esc(latest.type):''}</span></div><div class="ms-analysis-rows"><div><span>含关键事项</span><b>${change.length} 条</b><small>经理、费率、分红、申赎等</small></div><div><span>最新发布</span><b>${esc(latest?.date||'—')}</b><small>以公告原文为准</small></div></div><small class="ms-source">同花顺基金公告；关键词计数不代表事项已生效或必须操作。</small></section>`}
function marketReturnProfileWidget(points){const months=marketMonthlyReturns(points),up=months.filter(row=>row.value>0).length,down=months.filter(row=>row.value<0).length,max=Math.max(1,...months.map(row=>Math.abs(row.value)));return `<section class="ms-widget ms-analysis-widget ms-return-profile"><header><h2>月度表现</h2><span>最近 ${months.length} 个月份</span></header>${months.length?`<div class="ms-analysis-hero"><small>上涨月份 / 下跌月份</small><strong>${up} / ${down}</strong><span>复权净值相邻月末比较</span></div><div class="ms-month-list">${months.map(row=>`<div><span>${esc(row.month)}</span><i><em class="${tone(row.value)}" style="width:${Math.max(2,Math.abs(row.value)/max*100).toFixed(1)}%"></em></i><b class="${tone(row.value)}">${pct(row.value)}</b></div>`).join('')}</div>`:'<div class="ms-empty">历史净值不足，暂无月度表现</div>'}<small class="ms-source">扶摇复权净值；本月如尚未结束，使用最新可用净值。非账户收益。</small></section>`}
function marketWidgetName(id){return id.startsWith('metric:')?MS.metrics.find(row=>'metric:'+row.id===id)?.name||'自定义指标':MARKET_WIDGETS[id]||id}
function marketCustomWidget(id){const metric=MS.metrics.find(row=>'metric:'+row.id===id);if(!metric)return '<section class="ms-widget"><div class="ms-empty">指标定义不存在</div></section>';if(metric.method!=='drawdown')return `<section class="ms-widget"><header><h2>${esc(metric.name)}</h2></header><div class="ms-empty">披露持仓权重与当日行情未接入，当前无法计算。</div></section>`;const points=marketRangePoints(marketSeries(MS.fundCode),metric.window||'1y');if(points.length<2)return `<section class="ms-widget"><header><h2>${esc(metric.name)}</h2></header><div class="ms-empty">复权净值数据不足，无法计算。</div></section>`;let peak=-Infinity;const series=points.map(row=>{peak=Math.max(peak,Number(row.value));return {date:row.date,value:peak>0?(Number(row.value)/peak-1)*100:0}}),current=series.at(-1).value,worst=Math.min(...series.map(row=>row.value));return `<section class="ms-widget"><header><h2>${esc(metric.name)}</h2><small>v${num(metric.version)}</small></header><div class="ms-metrics"><div><small>当前回撤</small><strong>${num(current)}%</strong></div><div><small>区间最大回撤</small><strong>${num(worst)}%</strong></div></div>${marketSvg(series,'#c98585',90)}<small class="ms-source">${marketDate(points[0].date)}—${marketDate(points.at(-1).date)} · 复权净值历史峰值回撤 · ${esc(MS.fundCache.get(MS.fundCode)?.source||'数据待读取')}</small></section>`}
function marketFundStatus(code){if(MS.fundLoading.has(code))return '正在读取';if(MS.fundErrors.has(code))return '数据暂不可用';return MS.fundCache.has(code)?'已更新':'待读取'}
function marketEnsureFunds(){const codes=[...new Set([MS.fundCode,...state.watchlist.map(f=>f.code)].filter(code=>/^\d{6}$/.test(code)))].slice(0,25);for(const code of codes){if(MS.fundLoading.size>=3)break;if(MS.fundLoading.has(code)||MS.fundFetched.has(code)&&Date.now()-MS.fundFetched.get(code)<300000)continue;MS.fundLoading.add(code);api('/api/fund/nav?range=fyear&code='+encodeURIComponent(code)).then(data=>{MS.fundFetched.set(code,Date.now());MS.fundErrors.delete(code);if(data?.points?.length)MS.fundCache.set(code,data);else MS.fundErrors.set(code,'未返回复权净值')}).catch(error=>{MS.fundFetched.set(code,Date.now());MS.fundErrors.set(code,error.message)}).finally(()=>{MS.fundLoading.delete(code);if(['market','pages'].includes(state.nav)&&!state.conversationFocus)render();marketEnsureFunds();marketEnsurePublic()})}}
function marketEnsurePublic(){const codes=[...new Set([MS.fundCode,...state.watchlist.map(f=>f.code)].filter(code=>/^\d{6}$/.test(code)))].slice(0,25);for(const code of codes){if(MS.publicLoading.size>=3)break;if(MS.publicLoading.has(code)||MS.publicFetched.has(code)&&Date.now()-MS.publicFetched.get(code)<300000)continue;MS.publicLoading.add(code);api('/api/market/fund-detail?code='+encodeURIComponent(code)).then(data=>{MS.publicFetched.set(code,Date.now());MS.publicErrors.delete(code);MS.publicCache.set(code,data)}).catch(error=>{MS.publicFetched.set(code,Date.now());MS.publicErrors.set(code,error.message)}).finally(()=>{MS.publicLoading.delete(code);if(['market','pages'].includes(state.nav)&&!state.conversationFocus)render();marketEnsurePublic()})}}
function marketEnsureEstimates(){
  if(MS.estimateLoading)return;
  const codes=[...new Set([MS.fundCode,...(state.watchlist||[]).map(f=>f.code)].filter(code=>/^\d{6}$/.test(code)))].filter(code=>!MS.estimateFetched.has(code)||Date.now()-MS.estimateFetched.get(code)>90000).slice(0,25);
  if(!codes.length)return;
  MS.estimateLoading=true;
  api('/api/market/fund-intraday?codes='+encodeURIComponent(codes.join(','))).then(data=>{
    const fetched=Date.now();
    for(const code of codes)MS.estimateFetched.set(code,fetched);
    for(const row of data.funds||[])MS.estimateCache.set(row.code,row);
    MS.estimateError='';
  }).catch(error=>{MS.estimateError=error.message||'盘中参考暂不可用';for(const code of codes)MS.estimateFetched.set(code,Date.now())}).finally(()=>{
    MS.estimateLoading=false;
    if(['market','pages'].includes(state.nav)&&!state.conversationFocus)render();
    clearTimeout(MS.estimateTimer);
    MS.estimateTimer=setTimeout(()=>{if(['market','pages'].includes(state.nav))marketEnsureEstimates()},90000);
  });
}
function marketReferenceNav(formal,estimate){
  if(!formal?.date||!estimate?.asOf||n(estimate.changePct)===null)return null;
  if(Math.abs(Number(estimate.changePct))>=100)return null;
  const day=estimate.asOf.slice(0,10);
  const previous=new Date(day+'T00:00:00Z');
  if(Number.isNaN(previous.getTime())||formal.date>=day)return null;
  do{previous.setUTCDate(previous.getUTCDate()-1)}while([0,6].includes(previous.getUTCDay()));
  if(formal.date!==previous.toISOString().slice(0,10))return null;
  const value=Number(formal.value)*(1+Number(estimate.changePct)/100);
  return Number.isFinite(value)&&value>0?value:null;
}
function marketIndexQuote(code){return (state.marketIndices?.quotes||[]).find(row=>row.code===code)}
function marketToday(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return `${parts.year}-${parts.month}-${parts.day}`}
function marketEstimateFresh(estimate){return !!estimate?.asOf&&String(estimate.asOf).slice(0,10)===marketToday()}
function marketIndexTiles(compact=false){const quotes=(state.marketIndices?.quotes||[]).slice(0,compact?4:20);return `<div class="ms-index-tiles">${quotes.map(q=>`<button type="button" class="ms-index-tile" data-ms-action="index" data-code="${esc(q.code)}"><span>${esc(q.name)}</span><b class="${tone(q.changePct)}">${pct(q.changePct)}</b><strong>${num(q.point)} 点</strong><small>${esc(q.status)} · ${esc(dt(q.asOf))}</small></button>`).join('')||`<div class="ms-empty">${state.marketIndicesLoading?'正在读取行情':esc(state.marketIndicesError||'指数行情暂不可用')} <button type="button" data-ms-action="refresh">重试</button></div>`}</div><small class="ms-source">${esc(state.marketIndices?.source||'行情来源待确认')} · 指数涨跌不等于基金收益。</small>`}
function marketWatchRows(limit=99){
  const funds=(state.watchlist||[]).filter(f=>!MS.search||`${f.name||''}${f.code}`.includes(MS.search)).slice(0,limit);
  if(!funds.length)return `<div class="ms-empty">${MS.search?'没有匹配的自选基金':'还没有自选基金。'} ${!MS.search?'<button type="button" data-ms-action="add-watch">添加基金</button>':''}</div>`;
  const held=new Set((state.holdings?.funds||[]).map(row=>row.fundCode));
  const current=funds.filter(f=>marketEstimateFresh(MS.estimateCache.get(f.code))&&n(MS.estimateCache.get(f.code)?.changePct)!==null).length;
  return `<div class="ms-watch-status">${funds.length} 只自选 · ${held.size?funds.filter(f=>held.has(f.code)).length+' 只持有 · ':''}${current} 只有今日盘中参考</div><div class="ms-watch-table-wrap"><table class="ms-watch-table"><thead><tr><th>基金</th><th>盘中参考涨跌</th><th>近一月</th><th>近一年</th><th>正式净值</th></tr></thead><tbody>${funds.map(f=>{
    const data=MS.fundCache.get(f.code),publicData=MS.publicCache.get(f.code),points=data?.points||[];
    const month=marketReturn(marketRangePoints(points,'1m')),year=marketReturn(marketRangePoints(points,'1y'));
    const estimate=MS.estimateCache.get(f.code),reference=marketReferenceNav(publicData?.formalNav,estimate);
    const fresh=marketEstimateFresh(estimate),formalToday=publicData?.formalNav?.date===marketToday();
    const value=fresh&&reference!==null?'参考净值 ≈'+reference.toFixed(4):'参考净值暂不可算';
    const valid=fresh&&n(estimate?.changePct)!==null&&!formalToday;
    const note=formalToday?'今日正式净值已披露':valid?`${esc(estimate.metricLabel||'参考变化')} · ${esc(estimate.asOf)}`:estimate?.asOf?`上次数据 ${esc(estimate.asOf)}`:MS.estimateLoading?'读取中':esc(estimate?.status||MS.estimateError||'今日暂无参考数据');
    return `<tr><td><button type="button" class="ms-fund-name-link" data-ms-action="fund" data-code="${esc(f.code)}"><strong>${esc(f.name||data?.name||f.code)}</strong><small>${esc(f.code)}${held.has(f.code)?' · 持有':''} · 查看详情</small></button></td><td><button type="button" class="ms-estimate-cell ${valid?tone(estimate.changePct):''}" data-ms-action="estimate-detail" data-code="${esc(f.code)}"><strong>${valid?pct(estimate.changePct):'—'}</strong><small>${valid?value+' · ':''}${note}</small></button></td><td class="${tone(month)}"><strong>${pct(month)}</strong><small>复权 · ${data?marketDate(points.at(-1)?.date):marketFundStatus(f.code)}</small></td><td class="${tone(year)}"><strong>${pct(year)}</strong><small>复权 · ${data?marketDate(points.at(-1)?.date):marketFundStatus(f.code)}</small></td><td><span>${n(publicData?.formalNav?.value)!==null?Number(publicData.formalNav.value).toFixed(4):'—'}</span><small>${publicData?.formalNav?marketDate(publicData.formalNav.date):MS.publicLoading.has(f.code)?'读取中':MS.publicErrors.has(f.code)?'暂不可用':'净值待更新'}</small></td></tr>`;
  }).join('')}</tbody></table></div><small class="ms-source">盘中参考基于跟踪指数或最近披露重仓，仅供观察；正式净值以基金披露为准。近一月和近一年为复权净值涨跌。</small>`;
}
function marketWidget(id){if(id.startsWith('metric:'))return marketCustomWidget(id);if(id==='indices')return `<section class="ms-widget ms-indices"><header><h2>大盘概览</h2><div><button type="button" data-ms-action="tab" data-tab="indexes">查看全部</button></div></header>${marketIndexTiles(true)}</section>`;
  if(id==='index-focus'){const q=[...(state.marketIndices?.quotes||[])].filter(row=>n(row.changePct)!==null).sort((a,b)=>Math.abs(Number(b.changePct))-Math.abs(Number(a.changePct)))[0];return `<section class="ms-widget ms-focus"><header><h2>波动焦点</h2><button type="button" data-ms-action="tab" data-tab="indexes">查看指数</button></header>${q?`<div class="ms-focus-value"><span>${esc(q.name)}</span><b class="${tone(q.changePct)}">${pct(q.changePct)}</b><small>${num(q.point)} 点 · ${esc(q.status)} · ${esc(dt(q.asOf))}</small></div><small class="ms-source">${esc(state.marketIndices?.source||'行情来源待核验')} · 指数点位不能代替基金收益</small>`:'<div class="ms-empty">指数行情暂不可用</div>'}</section>`}
  if(id==='account'){const account=state.holdings,summary=account?.summary||{},funds=account?.funds||[];return `<section class="ms-widget ms-account-widget"><header><h2>我的持仓</h2><div><span class="ms-account-time">${account?'账户更新于 '+esc(dt(account.fetchedAt)):state.holdingsError?'账户暂不可用':'正在读取账户'}</span><button type="button" data-nav="holdings">查看持仓 →</button></div></header>${account?`<div class="ms-account-strip"><div><small>最近日收益 <em>账户数据</em></small><strong class="${tone(summary.newestIncome)}">${signed(summary.newestIncome)}</strong></div><div><small>累计持有收益</small><strong class="${tone(summary.holdIncome)}">${signed(summary.holdIncome)}</strong></div><div><small>持仓金额</small><strong>${money(summary.totalAmount)}</strong></div><div><small>持有基金</small><strong>${funds.length} 只</strong></div></div>`:`<div class="ms-account-empty">${state.holdingsError?esc(state.holdingsError):'账户数据读取中'} <button type="button" data-action="refresh-holdings">刷新账户</button></div>`}<small class="ms-source">账户日收益归属日期以同花顺账户接口为准；指数涨跌和盘中参考不计入这里。</small></section>`}
  if(id==='watchlist'||id==='long-watchlist')return `<section class="ms-widget ms-${id}"><header><h2>${id==='long-watchlist'?'长期表现':'自选基金'}</h2><div class="ms-watch-actions"><form id="ms-search-form" class="ms-watch-search"><input name="search" value="${esc(MS.search)}" placeholder="名称或代码" aria-label="搜索自选基金"><button type="submit">搜索</button>${MS.search?`<button type="button" data-ms-action="clear-search">清除</button>`:""}</form><button type="button" data-ms-action="add-watch">添加</button><button type="button" data-ms-action="import-watch">同步同花顺自选</button></div></header>${marketWatchRows(id==='watchlist'?99:8,true)}</section>`;
  if(id==='drawdown-list')return `<section class="ms-widget"><header><h2>波动观察</h2></header><div class="ms-list">${state.watchlist.slice(0,6).map(f=>{const points=marketRangePoints(marketSeries(f.code),'1y');return `<div><span>${esc(f.name||f.code)}</span><strong>${points.length?`${num(marketDrawdown(points))}%`:'—'}</strong></div>`}).join('')||'<div>请先添加自选基金</div>'}</div><small class="ms-source">基于近一年复权净值计算；历史回撤并非未来损失上限。</small></section>`;
  if(id==='fund-events'){const codes=[MS.fundCode],rows=(MS.publicCache.get(MS.fundCode)?.announcements||[]).map(item=>({...item,code:MS.fundCode})).slice(0,6);return `<section class="ms-widget"><header><h2>基金公告</h2></header>${rows.length?`<div class="ms-announcements">${rows.map(row=>`<div><span><small>${esc(row.date)} · ${esc(row.type)}</small><strong>${esc(row.title)}</strong></span>${row.url?`<a href="${esc(row.url)}" target="_blank" rel="noopener noreferrer">原文 ↗</a>`:''}</div>`).join('')}</div><small class="ms-source">来源：同花顺基金公告。页面仅展示公告标题，影响需结合原文判断。</small>`:`<div class="ms-empty">${codes.some(code=>MS.publicLoading.has(code))?'正在读取公告':'暂无可展示的公告'}</div>`}</section>`;}
  if(id==='alerts')return `<section class="ms-widget"><header><h2>我的提醒</h2><button type="button" data-ms-action="alerts">管理</button></header>${MS.alerts.length?`<div class="ms-list">${MS.alerts.slice(0,4).map(row=>`<div><span>${esc(row.name)}</span><small>${row.active?'仅本机打开时检查':'已暂停'}</small></div>`).join('')}</div>`:'<div class="ms-empty">尚未设置提醒</div>'}</section>`;
  const data=MS.fundCache.get(MS.fundCode),points=data?.points||[],visible=marketRangePoints(points),name=data?.name||marketWatchFund(MS.fundCode)?.name||MS.fundCode;
  if(id==='fund-holdings-impact')return marketHoldingsImpactWidget(MS.estimateCache.get(MS.fundCode));
  if(id==='fund-manager')return marketManagerWidget(data,MS.publicCache.get(MS.fundCode));
  if(id==='fund-technical')return marketTechnicalWidget(points);
  if(id==='fund-event-pulse')return marketEventPulseWidget(MS.publicCache.get(MS.fundCode));
  if(id==='fund-return-profile')return marketReturnProfileWidget(points);
  if(id==='fund-chart'){const change=marketReturn(visible),drawdown=marketDrawdown(visible);return `<section class="ms-widget ms-fund-chart"><header><h2>净值走势</h2><div class="ms-range">${[['1m','1月'],['3m','3月'],['6m','6月'],['1y','1年'],['3y','3年'],['all','全部数据']].map(([key,label])=>`<button type="button" data-ms-action="range" data-range="${key}" class="${MS.range===key?'active':''}" aria-pressed="${MS.range===key}">${label}</button>`).join('')}</div></header>${points.length?`<div class="ms-chart-summary"><div><span>区间涨跌</span><strong class="${tone(change)}">${pct(change)}</strong></div><div><span>最大回撤</span><strong>${drawdown===null?'—':pct(drawdown)}</strong></div></div>${marketDetailChart(visible)}<small class="ms-source">复权净值 · ${marketDate(visible[0]?.date)}—${marketDate(visible.at(-1)?.date)} · 扶摇 · 非个人持仓收益</small>`:`<div class="ms-empty">${esc(MS.fundErrors.get(MS.fundCode)||marketFundStatus(MS.fundCode))}</div>`}</section>`}
  if(id==='fund-performance')return `<section class="ms-widget ms-performance"><header><h2>阶段表现</h2><span>复权净值口径</span></header><div class="ms-performance-head"><span>区间</span><span>涨跌</span><span>最大回撤</span></div>${[['近一月','1m'],['近三月','3m'],['近六月','6m'],['近一年','1y'],['近三年','3y'],['全部数据','all']].map(([label,range])=>{const rows=marketRangePoints(points,range),value=marketReturn(rows),drawdown=marketDrawdown(rows);return `<div class="ms-performance-row"><span>${label}</span><strong class="${tone(value)}">${pct(value)}</strong><span>${drawdown===null?'—':pct(drawdown)}</span></div>`}).join('')}<small class="ms-source">截至 ${marketDate(points.at(-1)?.date)} · 扶摇；区间起点取首个可用净值日</small></section>`;
  if(id==='fund-drawdown'){const rows=marketRangePoints(points,'1y'),worst=marketDrawdown(rows);let peak=-Infinity;const series=rows.map(row=>{peak=Math.max(peak,Number(row.value));return {date:row.date,value:peak>0?100+((Number(row.value)/peak-1)*100):100}});return `<section class="ms-widget"><header><h2>近一年回撤</h2><strong>${worst===null?'—':num(worst)+'%'}</strong></header>${marketSvg(series,'#c98585',80)}<small class="ms-source">${rows.length?marketDate(rows[0].date)+'—'+marketDate(rows.at(-1).date):'数据不足'} · 历史峰值回撤，扶摇复权净值</small></section>`}
  if(id==='fund-profile'){const profile=MS.publicCache.get(MS.fundCode)?.profile;return `<section class="ms-widget ms-profile"><header><h2>基金资料</h2></header><dl><div><dt>基金类型</dt><dd>${esc(profile?.subtype||profile?.type||'—')}</dd></div><div><dt>风险等级</dt><dd>${esc(profile?.riskLevel||'—')}</dd></div><div><dt>基金经理</dt><dd>${esc(data?.manager||'—')}</dd></div><div><dt>成立日期</dt><dd>${esc(profile?.establishedAt||'—')}</dd></div><div><dt>起购金额</dt><dd>${profile?.minTradeAmount!==undefined&&profile.minTradeAmount!==null?'¥'+num(profile.minTradeAmount):'—'}</dd></div><div><dt>申购费率</dt><dd>${esc(profile?.preferredRate||'—')}</dd></div></dl><small class="ms-source">同花顺基金资料 · ${marketDate(MS.publicCache.get(MS.fundCode)?.fetchedAt)}</small></section>`;}
  if(id==='fund-disclosures'){const estimate=MS.estimateCache.get(MS.fundCode),holdings=estimate?.disclosedHoldings||[];return `<section class="ms-widget ms-holdings"><header><h2>重仓披露</h2><span>${estimate?.reportDate?'报告期 '+esc(estimate.reportDate):'报告期待读取'}</span></header>${holdings.length?`<div class="ms-holdings-head"><span>股票</span><span>披露占比</span><span>今日涨跌</span></div>${holdings.map(row=>`<div class="ms-holdings-row"><span><strong>${esc(row.name||row.code)}</strong><small>${esc(row.code)}</small></span><b>${Number.isFinite(Number(row.weightPct))?num(row.weightPct)+'%':'—'}</b><b class="${tone(row.changePct)}">${row.changePct===null||row.changePct===undefined?'—':pct(row.changePct)}</b></div>`).join('')}`:`<div class="ms-empty">${esc(estimate?.status||'持仓披露暂不可用')}</div>`}<small class="ms-source">公开报告期披露，可能滞后；不代表当前持仓。今日涨跌为股票行情，不是基金收益。</small></section>`}
  return '';
}
function marketWidgetFrame(id,index,page){return `<div class="ms-widget-frame" data-widget="${esc(id)}">${MS.editing&&MS.draft?`<div class="ms-widget-tools"><span>${esc(marketWidgetName(id))}</span><button type="button" data-ms-action="move" data-index="${index}" data-direction="-1" ${index===0?'disabled':''} aria-label="上移${esc(marketWidgetName(id))}">↑</button><button type="button" data-ms-action="move" data-index="${index}" data-direction="1" ${index===page.widgets.length-1?'disabled':''} aria-label="下移${esc(marketWidgetName(id))}">↓</button><button type="button" data-ms-action="remove" data-index="${index}" aria-label="移除${esc(marketWidgetName(id))}">×</button></div>`:''}${marketWidget(id)}</div>`}
function marketHome(){const page=marketCurrent(),widgets=(page.widgets||[]).filter(id=>marketCanUse(id,'home'));return `<div class="ms-layout ms-layout-${esc(page.sourceTemplate||page.id||'balanced-home')}">${widgets.map((id,index)=>marketWidgetFrame(id,index,page)).join('')}</div>${!widgets.length?'<div class="ms-empty">还没有内容。可以从“我的页面”选择布局。</div>':''}`}
function marketDetailStyle(page){const id=page.sourceTemplate||page.id;return MARKET_TEMPLATES.some(row=>row.kind==='detail'&&row.id===id)?id:'balanced-detail'}
function marketFundPage(){
  const data=MS.fundCache.get(MS.fundCode),publicData=MS.publicCache.get(MS.fundCode),watch=marketWatchFund(MS.fundCode),page=marketCurrent();
  const estimate=MS.estimateCache.get(MS.fundCode),reference=marketReferenceNav(publicData?.formalNav,estimate);
  const officialToday=publicData?.formalNav?.date===marketToday(),estimateFresh=marketEstimateFresh(estimate);
  const profile=publicData?.profile,official=publicData?.formalNav,year=marketRangePoints(data?.points||[],'1y');
  const estimateValue=officialToday?'今日正式净值已披露':estimateFresh&&reference!==null?`参考净值 ≈${reference.toFixed(4)}`:'';
  const estimateNote=officialToday?'以正式净值为准':estimateFresh?`${esc(estimate.asOf)} · ${esc(estimate.metricLabel||'参考变化')}`:estimate?.asOf?`上次参考：${esc(estimate.asOf)}`:esc(estimate?.status||'今日行情待更新');
  const month=marketRangePoints(data?.points||[],'1m');
  return `<div class="ms-fund-top ms-detail-style-${esc(marketDetailStyle(page))}"><button type="button" class="ms-fund-back" data-ms-action="back">← 返回上一页</button><div class="ms-fund-title"><div><h1>${esc(publicData?.profile?.name||data?.name||watch?.name||MS.fundCode)}</h1><span>${esc(MS.fundCode)}</span>${profile?.subtype||profile?.type?`<span class="ms-fund-chip">${esc(profile.subtype||profile.type)}</span>`:''}${profile?.riskLevel?`<span class="ms-fund-chip">${esc(profile.riskLevel)}</span>`:''}${MS.saveFeedback?`<span class="ms-saved-inline" role="status">${esc(MS.saveFeedback)}</span>`:''}</div><div class="ms-fund-actions"><button type="button" data-ms-action="toggle-watch" data-code="${esc(MS.fundCode)}">${watch?'★ 已自选':'☆ 加自选'}</button><button type="button" data-ms-action="community-detail">切换视图</button></div></div><div class="ms-fund-snapshot"><button type="button" data-ms-action="estimate-detail" data-code="${esc(MS.fundCode)}"><span>盘中参考涨跌 <em>估算</em></span><strong class="${estimateFresh&&!officialToday?tone(estimate?.changePct):''}">${estimateFresh&&!officialToday?pct(estimate?.changePct):'—'}</strong><small>${estimateNote}${estimateValue?' · '+estimateValue:''} ↗</small></button><div><span>近一月涨跌</span><strong class="${tone(marketReturn(month))}">${pct(marketReturn(month))}</strong><small>复权净值 · 截至 ${marketDate(month.at(-1)?.date)}</small></div><div><span>近一年涨跌</span><strong class="${tone(marketReturn(year))}">${pct(marketReturn(year))}</strong><small>复权净值 · 扶摇</small></div><div><span>最新单位净值</span><strong>${n(official?.value)!==null?Number(official.value).toFixed(4):'—'}</strong><small>正式披露 · ${marketDate(official?.date)}</small></div></div></div><div class="ms-layout ms-detail-layout ms-layout-${esc(marketDetailStyle(page))} ms-detail-style-${esc(marketDetailStyle(page))}">${(page.widgets||[]).map((id,index)=>marketWidgetFrame(id,index,page)).join('')}</div>`;
}
function pointsValue(points){const value=points?.at(-1)?.value;return value===undefined?'—':num(value)}
function marketIndexPage(){const quotes=state.marketIndices?.quotes||[],selected=marketIndexQuote(MS.indexCode),compared=MS.compare.map(marketIndexQuote).filter(Boolean),times=[...new Set(compared.map(q=>q.asOf))];return `<div class="ms-index-page"><div class="ms-index-list"><header><div class="ms-subpage-title"><button type="button" data-ms-action="tab" data-tab="home">← 我的行情</button><h2>指数行情</h2></div><div><button type="button" data-ms-action="refresh">刷新</button></div></header>${quotes.map(q=>`<div class="ms-index-row"><button type="button" data-ms-action="index" data-code="${esc(q.code)}"><strong>${esc(q.name)}</strong><small>${esc(q.code)} · ${esc(q.status)} · ${esc(dt(q.asOf))}</small></button><span>${num(q.point)}</span><b class="${tone(q.changePct)}">${pct(q.changePct)}</b><button type="button" data-ms-action="compare" data-code="${esc(q.code)}">${MS.compare.includes(q.code)?'✓ 已选':'＋ 对比'}</button></div>`).join('')||`<div class="ms-empty">${esc(state.marketIndicesError||'指数行情暂不可用')}</div>`}</div>${selected?`<section class="ms-index-detail"><header><h2>${esc(selected.name)}</h2><button type="button" data-ms-action="close-index">关闭</button></header><strong>${num(selected.point)} <b class="${tone(selected.changePct)}">${pct(selected.changePct)}</b></strong><small>${esc(selected.status)} · ${esc(dt(selected.asOf))} · ${esc(state.marketIndices?.source||'来源待核验')}</small><div class="ms-empty">分时与历史指数数据接口待接入。不能用当日点位生成历史走势。</div></section>`:''}${compared.length>1?`<section class="ms-index-compare"><header><h2>指数对比 · ${compared.length}/3</h2><button type="button" data-ms-action="clear-compare">清空</button></header>${times.length>1?'<p>数据时刻不同，仅列出快照，不直接排名。</p>':'<p>同一数据时刻的当日涨跌幅；指数点位不直接比较。</p>'}<div class="ms-metrics">${compared.map(q=>`<div><small>${esc(q.name)}</small><strong class="${tone(q.changePct)}">${pct(q.changePct)}</strong><span>${esc(dt(q.asOf))}</span></div>`).join('')}</div></section>`:''}</div>`}
