  if(id==='technical-detail')return '<div class="ms-plaza-mini ms-mini-technical"><div class="ms-mini-title">复权净值 · 技术观察</div><svg viewBox="0 0 300 75" preserveAspectRatio="none" aria-hidden="true"><path d="M0 59 L42 54 L76 61 L111 42 L151 45 L187 22 L224 33 L260 16 L300 25"/><path d="M0 63 L42 58 L76 54 L111 51 L151 44 L187 40 L224 35 L260 32 L300 29"/></svg><div class="ms-mini-legend"><span>净值走势</span><span>均线</span><span>回撤</span></div></div>';
  if(id==='news-focus-detail')return '<div class="ms-plaza-mini ms-mini-news"><div class="ms-mini-title">公告时间线</div><div><time>09.28</time><span>基金定期报告</span></div><div><time>09.21</time><span>经理变更公告</span></div><div><time>09.16</time><span>费率调整公告</span></div><small>事件时间 · 原文入口</small></div>';
  if(id==='performance-detail')return '<div class="ms-plaza-mini ms-mini-performance"><div class="ms-mini-title">业绩与风险</div><div class="ms-mini-perf-top"><span>阶段表现</span><span>最大回撤</span><span>同类比较</span></div><div class="ms-mini-bars"><i style="height:42%"></i><i style="height:72%"></i><i style="height:54%"></i><i style="height:88%"></i><i style="height:64%"></i><i style="height:76%"></i></div></div>';
