function marketPlaza(){
  const category=MS.communityTab==='detail'?'detail':'home',labels={detail:'基金详情视图',home:'行情视图'};
  const core=category==='detail'?['balanced-detail','performance-detail','holdings-detail','news-focus-detail','manager-detail','technical-detail']:['balanced-home','trend-home','long-home','compact-home'];
  const more=[];
  const official=MARKET_TEMPLATES.filter(row=>row.kind===category&&core.includes(row.id)).map(row=>({...row,official:true}));
  const extras=MARKET_TEMPLATES.filter(row=>row.kind===category&&more.includes(row.id)).map(row=>({...row,official:true}));
  const works=MS.works.filter(row=>row.kind===category);
  const renderCard=row=>`<article class="ms-template-card ms-plaza-card"><div class="ms-plaza-card-label"><span>${esc(row.group||'自定义')}</span><em>${row.official?'内置视图':'我的视图'}</em></div>${marketPlazaPreview(row)}<div class="ms-plaza-card-copy"><strong>${esc(row.name)}</strong><small>${esc(row.description||row.group||'按需查看基金信息')}</small></div><button type="button" data-ms-action="preview-work" data-id="${esc(row.id)}">${MS.newPageMode?'预览并新建':'预览这一版'} <span>↗</span></button></article>`;
  return `<div class="ms-community ms-plaza"><header><div class="ms-subpage-title"><button type="button" data-ms-action="community-back">← 返回</button><div><h2>${MS.newPageMode?'选一个布局':'选择视图'}</h2><small>${MS.newPageMode?'先预览，再保存。':'选好后先预览，确认再使用。'}</small></div></div></header><nav class="ms-community-tabs" aria-label="页面类型">${[['detail','基金详情'],['home','行情页']].map(([id,label])=>`<button type="button" data-ms-action="community-tab" data-tab="${id}" class="${category===id?'active':''}" aria-current="${category===id?'page':'false'}">${label}</button>`).join('')}</nav><div class="ms-plaza-heading"><strong>${labels[category]}</strong><span>${category==='detail'?'用选定基金的数据展示。':'选择首页先展示的内容。'}</span></div><div class="ms-template-grid">${official.map(renderCard).join('')}${works.map(renderCard).join('')||''}</div>${extras.length?`<details class="ms-more-views"><summary>更多视图 · ${extras.length} 个</summary><div class="ms-template-grid">${extras.map(renderCard).join('')}</div></details>`:''}<small class="ms-source">视图只改变展示内容，收益与行情仍按页面标注的数据来源读取。</small></div>`;
}
