function marketChoosePageKind(){if(MS.newPageDraft){MS.notice='先完成或取消当前草稿';render();return}MS.view='new-page';MS.landingHome=false;MS.newPageMode=false;MS.saveFeedback='';state.nav='pages';render()}
function marketNewPage(){return `<section class="ms-new-page"><header><button type="button" data-ms-action="new-page-back">← 我的页面</button><h1>新建页面</h1><p>先选内容，再挑布局。也可以在底部告诉助手想怎么设计。</p></header><div class="ms-new-page-grid"><article class="ms-new-page-card"><div class="ms-new-page-icon">◫</div><div><small>市场与自选</small><h2>行情页</h2><p>把指数、自选和关注的变化放在一起。</p></div><div class="ms-new-page-actions"><button type="button" data-ms-action="new-page-template" data-kind="home">选现成布局</button></div></article><article class="ms-new-page-card"><div class="ms-new-page-icon">⌁</div><div><small>一只基金</small><h2>基金详情</h2><p>围绕净值、表现、披露和公告组织页面。</p></div><div class="ms-new-page-actions"><button type="button" data-ms-action="new-page-template" data-kind="detail">选现成布局</button></div></article></div><p class="ms-new-page-note">只使用当前可用的数据；设计完成后先预览，再保存到“我的页面”。</p></section>`}
function marketStartAgentDesign(kind='home',code='',focusIndex=''){
  if(MS.newPageDraft){MS.notice='请先保存或取消当前草稿';render();return}
  if(kind==='detail'&&!/^\d{6}$/.test(String(code||''))){marketAgentFundDialog();return}
  if(MS.draft){MS.drafts[MS.draft.scope]=MS.draft;MS.draft=null}
  MS.activeWorkId=null;MS.newPageMode=true;MS.landingHome=false;MS.preview=null;MS.saveFeedback='';MS.notice='';
  MS.view=kind==='detail'?'fund':'home';MS.fundCode=kind==='detail'?String(code):'';state.nav='market';
  if(kind==='detail'){marketEnsureFunds();marketEnsurePublic();marketEnsureEstimates()}
  const indexName=focusIndex?marketIndexQuote(focusIndex)?.name||focusIndex:'';
  const prompt=kind==='detail'?`请用当前基金 ${code} 已有的真实数据设计一个简洁的基金详情页，先生成可预览草稿。重点放净值走势和阶段表现；缺少数据的模块请不要放入。`:indexName?`请围绕 ${indexName} 和当前可用的真实行情设计一个简洁的行情页，先生成可预览草稿；如果没有该指数的专属组件，请说明并用已有组件展示。`:'请用当前可用的真实行情和自选数据，设计一个简洁的行情页，先生成可预览草稿。把最值得关注的变化放前面。';
  openWorkbench(prompt,pageContext());
}
function marketAgentFundDialog(){const dialog=$('#panda-dialog'),host=$('#panda-dialog-content');host.innerHTML=`<form id="ms-agent-fund-form" class="ms-workspace-form"><h2>先选一只基金</h2><p>Agent 会围绕这只基金设计详情页。</p><label>基金代码<input name="code" pattern="[0-9]{6}" maxlength="6" placeholder="输入 6 位基金代码" list="ms-agent-funds" required></label><datalist id="ms-agent-funds">${(state.watchlist||[]).map(row=>`<option value="${esc(row.code)}">${esc(row.name)}</option>`).join('')}</datalist><div><button type="submit">继续设计</button><button type="button" data-ms-action="close-dialog">取消</button></div></form>`;if(!dialog.open)dialog.showModal()}
function marketAuxiliary(){const scope=marketScope(),versions=MS.history[scope]||[];return `${MS.widgetPicker?marketWidgetPicker():''}${MS.showVersions?`<section class="ms-side-sheet"><header><h2>版本记录</h2><button type="button" data-ms-action="versions">关闭</button></header>${versions.slice().reverse().map((row,i)=>`<div class="ms-list-row"><span>${esc(row.name)} · v${row.revision} · ${esc(dt(row.savedAt))}</span><button type="button" data-ms-action="restore" data-index="${versions.length-1-i}">载入草稿</button></div>`).join('')||'<div class="ms-empty">尚无保存版本</div>'}</section>`:''}${MS.showAlerts?marketAlertPanel():''}${MS.showMetrics?marketMetricPanel():''}`}
function marketWidgetPicker(){const kind=MS.view==='fund'?'detail':'home',page=MS.draft?.page||marketCurrent();const options=[...Object.entries(MARKET_WIDGETS),...MS.metrics.map(row=>['metric:'+row.id,row.name])].filter(([id])=>marketCanUse(id,kind)&&!page.widgets.includes(id));return `<section class="ms-side-sheet"><header><h2>添加组件</h2><button type="button" data-ms-action="add-widget">关闭</button></header><div class="ms-widget-choices">${options.map(([id,label])=>`<button type="button" data-ms-action="choose-widget" data-id="${esc(id)}">＋ ${esc(label)}</button>`).join('')||'<span>当前组件已全部加入</span>'}</div></section>`}
function marketAlertPanel(){return `<section class="ms-side-sheet"><header><h2>我的提醒</h2><button type="button" data-ms-action="alerts">关闭</button></header><p class="ms-source">当前仅在页面打开时检查指数快照；未接入后台通知。</p><form id="ms-alert-form"><label>指数<select name="code">${(state.marketIndices?.quotes||[]).map(q=>`<option value="${esc(q.code)}">${esc(q.name)}</option>`).join('')}</select></label><label>当日跌幅达到<input name="threshold" type="number" step="0.1" min="0.1" max="30" value="2" required> %</label><button type="submit">保存本机规则</button></form>${MS.alerts.map(row=>`<div class="ms-list-row"><span>${esc(row.name)} · 跌幅 ${num(row.threshold)}% · ${row.active?'页面打开时检查':'已暂停'} · ${row.triggeredAt?'最近触发 '+esc(dt(row.triggeredAt)):'尚未触发'}</span><button type="button" data-ms-action="alert-detail" data-id="${esc(row.id)}">详情</button><button type="button" data-ms-action="toggle-alert" data-id="${esc(row.id)}">${row.active?'暂停':'启用'}</button></div>`).join('')}${MS.alertSelected?`<div class="ms-alert-evidence"><strong>${esc(MS.alertSelected.name)} · 跌幅达到 ${num(MS.alertSelected.threshold)}%</strong>${MS.alertSelected.snapshot?`<p>触发快照：${num(MS.alertSelected.snapshot.point)} · ${pct(MS.alertSelected.snapshot.changePct)} · ${esc(dt(MS.alertSelected.snapshot.asOf))}</p><small>来源：${esc(MS.alertSelected.snapshot.source||'行情来源待确认')}</small>`:'<p>尚未触发；规则仅在客户端打开并刷新行情时检查。</p>'}</div>`:''}</section>`}
function marketMetricPanel(){return `<section class="ms-side-sheet"><header><h2>添加指标</h2><div><button type="button" data-ms-action="metrics">关闭</button></div></header>${MS.metricDraft?`<div class="ms-preview-bar"><span>AI 指标草稿：${esc(MS.metricDraft.name)} · ${MS.metricDraft.method==='drawdown'?'峰值回撤':'披露持仓贡献参考'} · ${esc(MS.metricDraft.window)}</span><button type="button" data-ms-action="confirm-metric">保存指标</button><button type="button" data-ms-action="cancel-metric">取消</button></div>`:''}<form id="ms-metric-form"><label>名称<input name="name" value="近一年历史峰值回撤" maxlength="40" required></label><label>计算方法<select name="method"><option value="drawdown">历史峰值回撤</option><option value="holding-contribution">披露重仓当日贡献参考</option></select></label><label>计算区间<select name="window"><option value="1y">近一年</option><option value="3m">近三月</option><option value="3y">近三年</option></select></label><button type="submit">创建指标</button></form><p class="ms-source">回撤按复权净值确定性计算。披露重仓贡献需要报告期持仓和股票行情，当前数据能力待接入。</p>${MS.metrics.map(row=>`<div class="ms-list-row"><span>${esc(row.name)} · ${row.method==='drawdown'?'可计算':'输入数据未接入'}</span><button type="button" data-ms-action="insert-metric" data-id="${esc(row.id)}" ${row.method!=='drawdown'?'disabled':''}>加到页面</button></div>`).join('')}</section>`}
function marketFundName(code){return state.watchlist.find(row=>row.code===code)?.name||state.holdings?.funds?.find(row=>row.fundCode===code)?.fundName||code}
function marketMyPages(){
  const layouts=Object.entries(MS.pages).filter(([scope,page])=>page&&typeof page==='object'&&(scope==='home'||/^fund:\d{6}$/.test(scope))).map(([scope,page])=>({scope,page}));
  const works=MS.works.filter(row=>row&&['home','detail'].includes(row.kind));
  const card=(page,subtitle,action,attr)=>`<button type="button" class="ms-my-page-card" data-ms-action="${action}" ${attr}><span class="ms-my-page-top"><em>${page.kind==='detail'?'基金详情':'行情页'}</em><small>v${esc(page.revision||1)}</small></span><strong>${esc(page.name||'未命名页面')}</strong><small>${subtitle}</small><span class="ms-my-page-widgets">${(page.widgets||[]).slice(0,3).map(id=>`<i>${esc(marketWidgetName(id))}</i>`).join('')}</span><span class="ms-my-page-open">打开页面 ↗</span></button>`;
  const cards=[...layouts.map(({scope,page})=>{const code=scope.startsWith('fund:')?scope.slice(5):'';return card({...page,kind:code?'detail':'home'},code?esc(marketFundName(code))+' · '+esc(code):'默认行情视图','open-saved-layout',`data-scope="${esc(scope)}"`)}),...works.map(page=>card(page,page.kind==='home'?'自定义行情页':page.sourceFundCode?esc(marketFundName(page.sourceFundCode))+' · '+esc(page.sourceFundCode):'自定义基金详情','open-saved-work',`data-id="${esc(page.id)}"`))];
  if(MS.newPageDraft?.page){const pending=MS.newPageDraft.page;cards.unshift(`<button type="button" class="ms-my-page-card ms-my-page-draft" data-ms-action="resume-new-draft"><span class="ms-my-page-top"><em>未保存草稿</em></span><strong>${esc(pending.name||'新页面')}</strong><small>继续预览并保存</small><span class="ms-my-page-widgets">${(pending.widgets||[]).slice(0,3).map(id=>`<i>${esc(marketWidgetName(id))}</i>`).join('')}</span><span class="ms-my-page-open">继续编辑 ↗</span></button>`)}
  return `<section class="ms-my-pages"><header><div><h1>已保存的页面</h1><p>打开页面时更新数据。</p></div><div><button type="button" data-ms-action="new-page">＋ 新建页面</button></div></header><div class="ms-my-pages-grid">${cards.join('')||'<div class="ms-empty">还没有页面。点击“新建页面”开始。</div>'}</div></section>`;
}
function marketStudioPage(){
  queueMicrotask(marketEnsureFunds);
  queueMicrotask(marketEnsurePublic);
  queueMicrotask(marketEnsureEstimates);
  const page=marketCurrent(),newDraft=!marketLandingHome()?marketActiveNewPageDraft():null;
  const showPreview=!marketLandingHome()&&(MS.view==='home'||MS.view==='fund')&&(newDraft||MS.preview&&MS.preview!==MS.newPageDraft?.page);
  const toolbar=MS.view==='home'?marketLandingHome()?`<div class="ms-workspace-toolbar"><div><strong>看行情</strong></div><div><button type="button" data-nav="pages">我的页面</button></div></div>`:`<div class="ms-workspace-toolbar"><div><strong>${esc(page?.name||'综合行情')}</strong>${MS.saveFeedback?`<small class="ms-saved-inline" role="status">${esc(MS.saveFeedback)}</small>`:''}</div><div><button type="button" data-ms-action="community-home">切换视图</button><button type="button" data-nav="pages">我的页面</button></div></div>`:'';
  const content=MS.view==='home'?marketHome():MS.view==='fund'?marketFundPage():MS.view==='indexes'?marketIndexPage():MS.view==='my-pages'?marketMyPages():MS.view==='new-page'?marketNewPage():marketPlaza();
  const designing=MS.newPageMode&&!newDraft&&(MS.view==='home'||MS.view==='fund');
  return `<div class="ms-root">${toolbar}${MS.notice?`<div class="ms-notice" role="alert">${esc(MS.notice)}<button type="button" data-ms-action="dismiss">×</button></div>`:''}${designing?'<div class="ms-designing-bar"><span>正在设计新页面 · 在右侧描述想看的内容</span><button type="button" data-ms-action="cancel-new-page">取消</button></div>':''}${showPreview?newDraft?`<div class="ms-preview-bar"><strong>${newDraft.existingWorkId?'页面修改':'新页面'} · ${esc(page.name)}</strong><div><button type="button" data-ms-action="save-new-page">${newDraft.existingWorkId?'保存修改':'保存页面'}</button><button type="button" data-ms-action="cancel-preview">取消</button></div></div>`:`<div class="ms-preview-bar"><strong>预览：${esc(page.name)}</strong><div><button type="button" data-ms-action="apply-preview">使用此视图</button><button type="button" data-ms-action="cancel-preview">取消</button></div></div>`:''}${marketEditTools()}${marketPicker()}${content}${marketAuxiliary()}</div>`;
}
function marketOpenSavedLayout(scope){if(!MS.pages[scope])return false;const hasDraft=MS.draft?.scope===scope||Boolean(MS.drafts[scope]);if(scope==='home')MS.returnTo=null;else marketCaptureReturn();MS.activeWorkId=null;MS.newPageMode=false;MS.landingHome=false;MS.preview=null;MS.editing=hasDraft;MS.notice=hasDraft?'正在查看未保存的页面草稿':'';MS.fundCode=scope.startsWith('fund:')?scope.slice(5):'';MS.view=scope==='home'?'home':'fund';state.nav='market';render();if(MS.view==='fund'){marketEnsureFunds();marketEnsurePublic();marketEnsureEstimates()}return true}
document.addEventListener('click',event=>{const target=event.target.closest('[data-ms-action="open-saved-layout"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();marketOpenSavedLayout(target.dataset.scope)},true);
document.addEventListener('click',event=>{const target=event.target.closest('[data-ms-action="save-new-page"],[data-ms-action="cancel-preview"]');if(!target||MS.newPageDraft?.scope!==marketScope())return;event.preventDefault();event.stopImmediatePropagation();if(target.dataset.msAction==='save-new-page')marketCommitNewPage();else marketCancelNewPage()},true);
function marketAlertCheck(){for(const row of MS.alerts){if(!row.active)continue;const q=marketIndexQuote(row.code);if(!q||!/^交易中$|^已收盘$/.test(q.status)||!Number.isFinite(Number(q.changePct)))continue;const crossed=Number(q.changePct)<=-Number(row.threshold);const day=marketDate(q.asOf);if(crossed&&!row.crossed&&row.triggeredDay!==day){row.triggeredAt=q.asOf;row.triggeredDay=day;row.snapshot={name:q.name,point:q.point,changePct:q.changePct,asOf:q.asOf,source:state.marketIndices?.source};MS.notice=`${q.name} 日跌幅达到 ${row.threshold}% · ${marketDate(q.asOf)}`}row.crossed=crossed}marketPersist()}
function marketEstimateDetail(code){
  const row=MS.estimateCache.get(code),formal=MS.publicCache.get(code)?.formalNav;
  const name=marketWatchFund(code)?.name||code,reference=marketReferenceNav(formal,row);
  const basis=row?.metricLabel==='跟踪指数涨跌幅'?`跟踪指数：${esc(row.basisName||'—')}`:`最近披露重仓：${esc(row?.reportDate||'日期未取得')} · 有效股票 ${esc(row?.validStockCount??'—')} 只 · 行情覆盖 ${esc(row?.quoteCoveragePct??'—')}%`;
  const fresh=marketEstimateFresh(row),formalToday=formal?.date===marketToday();
  const value=reference===null?'暂不能给出单位净值参考值':`约 ${reference.toFixed(4)}（${pct(row.changePct)}）`;
  const detail=formalToday?'<p class="ms-estimate-value">今日正式净值已披露，以正式净值为准</p>':!fresh?`<p>今日暂无盘中参考数据。${row?.asOf?'上次更新时间：'+esc(row.asOf):esc(row?.status||MS.estimateError||'')}</p>`:row?.changePct===null||row?.changePct===undefined?`<p>${esc(row?.status||MS.estimateError||'今日行情暂不可用')}</p>`:`<p class="ms-estimate-value">${value}</p><p>${basis}</p><p>行情时间：${esc(row.asOf||'—')}</p><p>计算：${formal&&reference!==null?`${Number(formal.value).toFixed(4)}（${esc(formal.date)} 正式净值）×（1＋${pct(row.changePct)}）`:formal?'正式净值日期与行情日期不连续，无法推算单位净值':'正式净值暂未取得，无法推算单位净值'}</p>`;
  const host=$('#panda-dialog-content'),dialog=$('#panda-dialog');
  host.innerHTML=`<div class="ms-estimate-dialog"><h2>${esc(name)} · 盘中参考依据</h2>${detail}<small>来源：东方财富基金资料与重仓披露、腾讯证券行情。主动基金仅反映已披露重仓，不代表全仓。该值不是基金正式净值或账户收益。</small><button type="button" data-ms-action="close-dialog">关闭</button></div>`;
  if(!dialog.open)dialog.showModal();
}
document.addEventListener('click',event=>{const target=event.target.closest('[data-ms-action="estimate-detail"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();marketEstimateDetail(target.dataset.code)},true);
document.addEventListener('click',async event=>{const target=event.target.closest('[data-ms-action="toggle-watch"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();const code=target.dataset.code,remove=!!marketWatchFund(code);try{const data=await api('/api/watchlist',{code,name:MS.publicCache.get(code)?.profile?.name||MS.fundCache.get(code)?.name||code,remove});state.watchlist=data.watchlist||[];MS.notice=remove?'已从自选移除':'已加入自选';render()}catch(error){MS.notice=error.message||'自选操作未完成';render()}},true);
function marketWorkspaceEditor(){const config=workbenchReadConfig(),host=$('#panda-dialog-content'),dialog=$('#panda-dialog'),labels={market:'看行情',library:'找策略',holdings:'看持仓'},orders=[['market','library','holdings'],['market','holdings','library'],['library','market','holdings'],['library','holdings','market'],['holdings','market','library'],['holdings','library','market']];host.innerHTML=`<form id="ms-workspace-form" class="ms-workspace-form"><h2>自定义总览工作台</h2><strong>显示模块</strong><div class="ms-workspace-choices">${Object.entries(labels).map(([id,label])=>`<label><input type="checkbox" name="module" value="${id}" ${config.modules.includes(id)?'checked':''}>${label}</label>`).join('')}</div><label>排列顺序<select name="order">${orders.map(order=>`<option value="${order.join(',')}">${order.map(id=>labels[id]).join(' → ')}</option>`).join('')}</select></label><label class="ms-workspace-toggle"><input type="checkbox" name="pulse" value="1" ${config.pulse?'checked':''}>显示账户与计划概览</label><div><button type="submit">保存工作台</button><button type="button" data-ms-action="close-dialog">取消</button></div></form>`;host.querySelector('[name="order"]').value=[...config.modules,...Object.keys(labels).filter(id=>!config.modules.includes(id))].join(',');if(!dialog.open)dialog.showModal()}
document.addEventListener('click',event=>{
  const target=event.target.closest('[data-ms-action="new-page-back"],[data-ms-action="new-page-template"],[data-ms-action="new-page-agent"],[data-ms-action="cancel-new-page"],[data-ms-action="design-current"],[data-ms-action="design-index-page"],[data-ms-action="resume-new-draft"]');
  if(!target)return;
  event.preventDefault();event.stopImmediatePropagation();
  const action=target.dataset.msAction,kind=target.dataset.kind||'home';
  if(action==='resume-new-draft'){const pending=MS.newPageDraft;if(!pending?.page)return;MS.activeWorkId=pending.existingWorkId||null;MS.newPageMode=!pending.existingWorkId;MS.landingHome=false;MS.view=pending.page.kind==='detail'?'fund':'home';MS.fundCode=pending.page.sourceFundCode||pending.scope.match(/^fund:(\d{6})$/)?.[1]||'';MS.preview=pending.page;state.nav='market';render();if(MS.view==='fund'){marketEnsureFunds();marketEnsurePublic();marketEnsureEstimates()}return}
  if(action==='new-page-back'||action==='cancel-new-page'){MS.newPageMode=false;MS.preview=null;MS.saveFeedback='';MS.view='my-pages';state.nav='pages';render();return}
  if(action==='new-page-template'){marketOpenViewPicker(kind,'new-page',true);return}
  if(action==='new-page-agent'){marketStartAgentDesign(kind);return}
  if(action==='design-index-page'){marketStartAgentDesign('home','',MS.indexCode);return}
  const prompt=marketActiveNewPageDraft()?'请根据当前预览草稿继续优化页面布局，保留我没有要求删除的内容，并重新给我预览。':MS.newPageMode?MS.view==='fund'?`请为基金 ${MS.fundCode} 用已有数据设计一个简洁的详情页，先给我预览。`:'请用当前可用的行情数据设计一个简洁页面，先给我预览。':MS.view==='fund'?`请帮我调整当前基金 ${MS.fundCode} 的详情页：先看现在有哪些内容，再建议更清楚的布局，并生成可预览的页面草稿。`:'请帮我调整当前行情页：先看现在有哪些内容，再建议更清楚的布局，并生成可预览的页面草稿。';
  openWorkbench(prompt,pageContext());
},true);
