document.addEventListener('click',event=>{const target=event.target.closest('[data-workbench-action],[data-ms-action="community-tab"],[data-ms-action="community-back"],[data-ms-action="community-detail"],[data-ms-action="community-home"],[data-ms-action="community-edit"],[data-ms-action="apply-workspace"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();const action=target.dataset.workbenchAction||target.dataset.msAction;if(action==='community'){MS.communityReturn='workspace';MS.communityTab='detail';MS.view='community';state.nav='market'}else if(action==='edit'){marketWorkspaceEditor();return}else if(action==='community-tab'){MS.communityTab=target.dataset.tab}else if(action==='community-home'){marketOpenViewPicker('home',MS.view)}else if(action==='community-detail'){marketOpenViewPicker('detail','fund')}else if(action==='community-back'){if(MS.communityReturn==='workspace'){state.nav='workbench';MS.view='home'}else if(MS.communityReturn==='new-page'){state.nav='pages';MS.view='new-page';MS.newPageMode=false}else if(MS.communityReturn==='my-pages'){state.nav='pages';MS.view='my-pages'}else if(MS.communityReturn==='fund'){state.nav='market';MS.view='fund'}else{state.nav='market';MS.view='home'}}else if(action==='community-edit'){MS.view=MS.communityTab==='detail'?'fund':'home';if(MS.view==='fund'&&!MS.fundCode){MS.notice='先选择一只基金，再调整详情视图';render();return}marketDraftFromCurrent();MS.editing=true}else if(action==='apply-workspace'){const template=marketTemplate(target.dataset.id);if(template?.kind==='workspace'){localStorage.setItem('suvi-workbench-config',JSON.stringify({modules:template.modules,pulse:template.pulse}));state.nav='workbench';MS.view='home';MS.notice='工作台布局已切换';marketWorkspaceEditor();render();return}}render()},true);
