function marketStartWorkPreview(work,code='',creating=false){
  const kind=work.kind==='detail'?'detail':'home';
  if(kind==='detail'&&!/^\d{6}$/.test(String(code||'')))return false;
  if(!creating&&!MS.returnTo){const fromMyPages=MS.communityReturn==='my-pages',fromFund=MS.communityReturn==='fund';MS.returnTo={nav:fromMyPages?'pages':'market',view:fromMyPages?'my-pages':fromFund?'fund':'home',fundCode:fromFund?MS.fundCode:'',range:MS.range,search:MS.search,selectedHoldingCode:state.selectedHoldingCode,holdingsAccountScope:state.holdingsAccountScope,activeWorkId:null,newPageMode:false,landingHome:MS.landingHome}}
  state.nav='market';MS.view=kind==='detail'?'fund':'home';MS.landingHome=false;MS.activeWorkId=null;MS.fundTrail=[];MS.picker=false;MS.saveFeedback='';
  if(kind==='detail'){MS.fundCode=String(code);marketEnsureFunds();marketEnsurePublic();marketEnsureEstimates()}
  const page=marketCopy(work);page.kind=kind;page.sourceTemplate=work.sourceTemplate||work.id;
  if(kind==='detail')page.sourceFundCode=String(code);
  if(creating){page.id=marketNewWorkId();page.revision=0;page.createdAt=page.createdAt||new Date().toISOString();MS.newPageMode=true;MS.newPageDraft={scope:marketScope(),page,updatedAt:new Date().toISOString()};MS.preview=page;MS.notice='';MS.saveFeedback=''}
  else{MS.newPageMode=false;MS.newPageDraft=null;MS.preview=page}
  render();return true;
}
function marketOpenSavedWork(work,code=''){
  if(MS.newPageDraft){MS.notice='请先保存或取消当前的新页面草稿，再打开其他页面';render();return false}
  const kind=work.kind==='detail'?'detail':'home';if(kind==='detail'&&!/^\d{6}$/.test(String(code||'')))return false;
  MS.returnTo=null;MS.fundTrail=[];MS.activeWorkId=work.id;MS.newPageMode=false;MS.newPageDraft=null;MS.preview=null;MS.editing=false;MS.saveFeedback='';MS.landingHome=false;MS.view=kind==='detail'?'fund':'home';state.nav='market';
  if(kind==='detail'){MS.fundCode=String(code);marketEnsureFunds();marketEnsurePublic();marketEnsureEstimates()}else MS.fundCode='';render();return true;
}
