document.addEventListener('click',async event=>{const target=event.target.closest('[data-ms-action]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();const a=target.dataset.msAction;try{if(a==='tab'){MS.view=target.dataset.tab;MS.preview=null;MS.picker=false;MS.search='';render()}else if(a==='new-page'){marketChoosePageKind()}else if(a==='choose-page-kind'){if($('#panda-dialog')?.open)$('#panda-dialog').close();marketOpenViewPicker(target.dataset.kind,MS.view,true)}else if(a==='view-picker'){marketOpenViewPicker(target.dataset.kind||'home',MS.view)}else if(a==='fund')marketShowFund(target.dataset.code);else if(a==='back')marketBack();else if(a==='index'){MS.indexCode=target.dataset.code;MS.view='indexes';render()}else if(a==='close-index'){MS.indexCode='';render()}else if(a==='compare'){const code=target.dataset.code;if(MS.compare.includes(code))MS.compare=MS.compare.filter(x=>x!==code);else if(MS.compare.length<3)MS.compare.push(code);else MS.notice='最多选择 3 个指数';render()}else if(a==='clear-compare'){MS.compare=[];render()}else if(a==='clear-search'){MS.search='';render()}else if(a==='refresh'){loadMarketIndices(true)}else if(a==='range'){MS.range=target.dataset.range;render()}else if(a==='picker'){MS.picker=!MS.picker;render()}else if(a==='close-picker'){MS.picker=false;render()}else if(a==='preview-template'){MS.preview=marketCloneTemplate(target.dataset.id);MS.picker=false;render()}else if(a==='preview-work'){const work=MS.works.find(x=>x.id===target.dataset.id)||marketTemplate(target.dataset.id);if(work){MS.view=work.kind==='detail'?'fund':'home';if(MS.view==='fund'&&!MS.fundCode){const first=state.watchlist[0];if(!first){MS.notice='先添加一只自选基金，再预览基金详情';render();return}MS.fundCode=first.code}MS.preview=marketCopy(work);MS.preview.sourceTemplate=work.sourceTemplate||work.id;MS.picker=false;render()}}else if(a==='apply-preview'||a==='copy-work'){if(a==='copy-work'){const work=MS.works.find(x=>x.id===target.dataset.id);if(!work)return;MS.preview=marketCopy(work);MS.view=work.kind==='detail'?'fund':'home'}marketDraftFromCurrent();if(MS.preview){MS.draft.page=marketCopy(MS.preview);MS.draft.page.sourceTemplate=MS.draft.page.sourceTemplate||MS.draft.page.id;MS.draft.page.id='personal-'+Date.now();MS.preview=null}MS.editing=true;MS.notice='已载入页面草稿，保存后生效';marketPersist();render()}else if(a==='cancel-preview'){MS.preview=null;if(MS.returnTo)marketBack();else render()}else if(a==='edit'){marketDraftFromCurrent();MS.editing=true;render()}else if(a==='open-ai'){state.agentOpen=true;render();$('#agent-input')?.focus()}else if(a==='ai-edit'){state.agentOpen=true;render();const input=$('#agent-input');if(input){input.value='把自选基金放在大盘上面，其他看板保持不变。';input.focus()}}else if(a==='ai-new-page'){state.agentOpen=true;render();const input=$('#agent-input');if(input){input.value=MS.view==='fund'?'用当前基金可用的数据新建一个详情页，先给我预览。':'用当前可用的指数和自选基金数据新建一个行情页，先给我预览。';input.focus()}}else if(a==='cancel-edit'){MS.editing=false;render()}else if(a==='save')marketSave();else if(a==='undo'||a==='redo')marketUndo(a);else if(a==='move'||a==='remove'){const index=Number(target.dataset.index);marketModify(page=>{if(a==='remove')page.widgets.splice(index,1);else{const next=index+Number(target.dataset.direction);if(next>=0&&next<page.widgets.length)[page.widgets[index],page.widgets[next]]=[page.widgets[next],page.widgets[index]]}})}else if(a==='add-widget'){marketDraftFromCurrent();MS.editing=true;MS.widgetPicker=!MS.widgetPicker;render()}else if(a==='choose-widget'){const id=target.dataset.id,kind=MS.view==='fund'?'detail':'home';if(!marketCanUse(id,kind)||(!MARKET_WIDGETS[id]&&!id.startsWith('metric:')))return;marketModify(page=>{if(!page.widgets.includes(id))page.widgets.push(id)});MS.widgetPicker=false;render()}else if(a==='versions'){MS.showVersions=!MS.showVersions;render()}else if(a==='restore')marketRestore(Number(target.dataset.index));else if(a==='alerts'){MS.showAlerts=!MS.showAlerts;render()}else if(a==='alert-detail'){MS.alertSelected=MS.alerts.find(x=>x.id===target.dataset.id)||null;MS.showAlerts=true;render()}else if(a==='toggle-alert'){const row=MS.alerts.find(x=>x.id===target.dataset.id);if(row){row.active=!row.active;marketPersist();render()}}else if(a==='metrics'){MS.showMetrics=!MS.showMetrics;render()}else if(a==='ai-metric'){state.agentOpen=true;render();const input=$('#agent-input');if(input){input.value='帮我设计一个近一年历史峰值回撤指标，放到当前基金详情页。请说明输入与计算口径。';input.focus()}}else if(a==='confirm-metric'){if(MS.metricDraft){const method=MS.metricDraft.method;MS.metrics.push({id:'metric-'+Date.now(),...MS.metricDraft,inputs:method==='drawdown'?['adjustedNavSeries']:['disclosedAssetWeights','stockDailyReturns'],output:method==='drawdown'?'percentSeries':'percentContribution',missingPolicy:'noResult',version:1,createdAt:new Date().toISOString()});MS.metricDraft=null;marketPersist();MS.notice=method==='drawdown'?'指标已保存，可添加到基金详情':'指标已保存；输入数据暂未接入';render()}}else if(a==='cancel-metric'){MS.metricDraft=null;render()}else if(a==='insert-metric'){const row=MS.metrics.find(x=>x.id===target.dataset.id);if(row?.method==='drawdown'&&MS.view==='fund'){const id='metric:'+row.id;marketModify(page=>{if(!page.widgets.includes(id))page.widgets.push(id)});MS.showMetrics=false;render()}else MS.notice='先打开基金详情页';render()}else if(a==='import-watch'){const host=$('#panda-dialog-content'),dialog=$('#panda-dialog');host.innerHTML='<div class="ms-sync-dialog"><h2>同步同花顺自选</h2><p>当前账户连接只提供持仓和交易查询，尚未提供账户自选读取接口。接入该接口后，可在这里同步并合并现有自选。</p><div><button type="button" data-ms-action="add-watch">先添加单只基金</button><button type="button" data-ms-action="close-dialog">关闭</button></div></div>';dialog.showModal()}else if(a==='add-watch'){const host=$('#panda-dialog-content'),dialog=$('#panda-dialog');host.innerHTML='<h2>添加自选基金</h2><form id="ms-watch-form"><label>6 位基金代码<input name="code" pattern="[0-9]{6}" maxlength="6" required></label><label>基金名称<input name="name" maxlength="80"></label><button type="submit">添加自选</button><button type="button" data-ms-action="close-dialog">取消</button></form>';if(!dialog.open)dialog.showModal()}else if(a==='close-dialog')$('#panda-dialog').close();else if(a==='ask'||a==='ask-fund'){const prompt=MS.view==='fund'?`请根据当前基金 ${MS.fundCode} 的可用复权净值和真实来源，解释它最近的变化；正式净值和公告数据若不可用请直说。`:MS.view==='indexes'&&MS.indexCode?`请解释 ${marketIndexQuote(MS.indexCode)?.name||'当前指数'} 的当前行情，说明数据时刻和可核实依据。`:'请结合今天的大盘、自选基金和我账户中实际持有的基金，指出值得关注的变化；区分指数行情、盘中参考、正式净值与账户收益，缺少关联依据时请直说。';state.agentOpen=true;render();const input=$('#agent-input');if(input){input.value=prompt;input.focus()}}else if(a==='share'){if(MS.draft||MS.preview){MS.notice='请先保存页面，再创建分享预览';render();return}const source=marketCurrent();const sanitized={id:'local-work-'+Date.now(),name:source.name,kind:source.kind||'home',widgets:source.widgets.filter(id=>MARKET_WIDGETS[id]||id.startsWith('metric:')&&MS.metrics.some(row=>'metric:'+row.id===id)),metrics:MS.metrics.filter(row=>source.widgets.includes('metric:'+row.id)).map(row=>({name:row.name,method:row.method,window:row.window,version:row.version,inputs:row.inputs,output:row.output,missingPolicy:row.missingPolicy})),sourceRevision:source.revision||0,createdAt:new Date().toISOString(),binding:source.kind==='detail'?'$currentFund':'$myWatchlist'};MS.communityItem=sanitized;const host=$('#panda-dialog-content');host.innerHTML=`<h2>分享预览</h2><p>本机演示作品；跨用户社区发布服务待接入。</p><div class="ms-template-preview">${sanitized.widgets.map(id=>`<span>${esc(marketWidgetName(id))}</span>`).join('')}</div><p>使用者将绑定自己的${sanitized.kind==='detail'?'基金':'自选'}。不包含账户金额、聊天与通知设置。</p><button type="button" data-ms-action="save-work">保存到本机作品</button><button type="button" data-ms-action="close-dialog">取消</button>`;$('#panda-dialog').showModal()}else if(a==='save-work'){if(MS.communityItem){MS.works.push(MS.communityItem);MS.communityItem=null;marketPersist();$('#panda-dialog').close();MS.notice='已保存到本机作品';render()}}else if(a==='dismiss'){MS.notice='';render()}}catch(error){MS.notice=error.message||'操作未完成';render()}},true);
