document.addEventListener('submit',async event=>{if(!['ms-watch-form','ms-alert-form','ms-metric-form','ms-search-form'].includes(event.target.id))return;event.preventDefault();event.stopImmediatePropagation();const form=Object.fromEntries(new FormData(event.target));try{if(event.target.id==='ms-search-form'){MS.search=String(form.search||'').trim().slice(0,80);render();return}if(event.target.id==='ms-watch-form'){const data=await api('/api/watchlist',{code:form.code,name:form.name});state.watchlist=data.watchlist||[];$('#panda-dialog').close();MS.fundErrors.delete(form.code);MS.publicErrors.delete(form.code);marketEnsureFunds();marketEnsurePublic();MS.notice='已加入自选'}else if(event.target.id==='ms-alert-form'){const quote=marketIndexQuote(form.code),threshold=Number(form.threshold);if(!quote||!Number.isFinite(threshold)||threshold<=0)throw Error('请选择可用指数和有效跌幅');MS.alerts.push({id:'alert-'+Date.now(),code:form.code,name:quote.name,threshold,active:true,crossed:Number(quote.changePct)<=-threshold,triggeredDay:null});marketPersist();MS.notice='本机提醒规则已保存，仅在页面打开时检查'}else if(event.target.id==='ms-metric-form'){const method=form.method;if(!['drawdown','holding-contribution'].includes(method))throw Error('不支持的计算方法');MS.metrics.push({id:'metric-'+Date.now(),name:String(form.name).slice(0,40),method,window:['1y','3m','3y'].includes(form.window)?form.window:'1y',inputs:method==='drawdown'?['adjustedNavSeries']:['disclosedAssetWeights','stockDailyReturns'],output:method==='drawdown'?'percentSeries':'percentContribution',missingPolicy:'noResult',version:1,createdAt:new Date().toISOString()});marketPersist();MS.notice=method==='drawdown'?'指标已创建；打开基金详情可添加到页面':'指标草稿已保存，所需输入数据待接入'}render()}catch(error){MS.notice=error.message;render()}},true);
